ANNOTATIONS = [
    (7, 'after', r'''本文件是 PowerShell 版的路径校验：从 AST 里抽出命令涉及的文件路径，逐个对照会话允许的工作目录。与 BashTool/pathValidation.ts 同构，但按 cmdlet 大小写不敏感、参数前缀匹配等 PowerShell 语义重写。'''),
    (50, 'after', r'''PowerShell 通配符只有 * ? [ ] 四种——花括号是字面字符，不做展开。把 {} 也算进通配符会让 ./{x}/passwd 这类路径走 glob 基目录截断，而不是完整路径的符号链接解析。'''),
    (87, 'after', r'''每类 cmdlet 一份「参数户口本」：pathParams 是路径参数（要校验）、knownSwitches 是开关（不吃值）、knownValueParams 是吃值但不是路径的参数（如 -Encoding）。安全模型：任何不在这三张表里的 -Param 直接判 hasUnvalidatablePathArg → ask，终结已往「缺个开关就被未知参数启发式吞掉下一个参数（可能是位置路径）」的打地鼠循环。'''),
    (125, 'before', r'''─── 写操作类 cmdlet ───'''),
    (267, 'after', r'''New-Item 的 -Name 由 PowerShell 相对 -Path 解析（含 .. 穿越），而 validatePath 只按 cwd 解析——New-Item -Path /allowed -Name ../secret/evil 实际创建 /secret/evil，校验却落在别处。这是已知的 deny→ask 降级，不是 fail-safe；-Name 进 leafOnlyPathParams 只放行简单叶子名。'''),
    (375, 'before', r'''─── 读操作类 cmdlet ───'''),
    (578, 'before', r'''带输出参数的写路径 cmdlet：缺了这几条，-OutFile/-DestinationPath 就能往任意路径写而无人校验。'''),
    (765, 'after', r'''配置表到此结束。注意每条注释都是真实事故的尸检报告：Out-File/Tee-Object/Export-Csv 缺失导致 Edit deny 只 ask 不 deny；mkdir/ren/si 经 COMMON_ALIASES 解析后不在表里，直接绕过 deny。'''),
    (782, 'after', r'''参数名匹配吃 PowerShell 的前缀匹配：-Lit 能匹配 -LiteralPath。'''),
    (803, 'after', r'''冒号语法（-Path:safe.txt,/etc/passwd）把数组藏进单个 CommandParameterAst 里，外层元素类型看不到内层表达式——只能文本级识别逗号/括号/变量等掩码字符。'''),
    (815, 'after', r'''目录列表最多列 5 个，超出折叠成「and N more」——报错消息是给人看的，别刷屏。'''),
    (829, 'after', r'''~ 开头展开到 homedir()。'''),
    (846, 'after', r'''先查「用户原样输入的路径」再查规范化后的：safeResolvePath/realpathSync 会把 / 规范化成 C:\（Windows）、把 /var 改写成 /private/var（macOS），恰好破坏 isDangerousRemovalPath 的字符串比较。按用户敲的形态（~ 展开、反斜杠归一）才能认出 / ~ /etc /usr 这些危险形状。'''),
    (857, 'after', r'''删除系统路径是硬 deny——用户无法批准删 system32。'''),
    (977, 'after', r'''单路径允许性判断，顺序即优先级：deny 规则 → 内部可写路径（plan/scratchpad/memory，必须先于安全校验因为 .claude 本身就是危险目录）→ 自动编辑安全校验 → 工作目录内 → 沙箱写白名单 → allow 规则。'''),
    (1008, 'after', r'''「猜出来的路径」只查 deny 规则，绝不自动允许：猜不中就老实落到 ask。null 字节会让 expandPath 抛错，先挡掉。'''),
    (1264, 'after', r'''validatePath 是路径校验的主干，六层安全闸门依次过：反引号转义 → :: 模块限定 provider 路径 → UNC → $/% 变量展开 → 非文件系统 provider（env:/HKLM:）→ 通配符。每一层都是「静态不可验证 → ask」，附带 deny 猜测兜底。'''),
    (1278, 'after', r'''glob 基目录 = 第一个通配符字符之前的目录。只 realpath 这一段，glob 展开出来的符号链接永远看不到——所以读操作的 glob 也只能 ask（见 finding #15 的长注释）。'''),
    (1294, 'after', r'''只有 StringConstant 和 Parameter 两类元素类型有静态可知的字符串值。变量、可展开字符串、数组字面量在这里就 fail-safe 挡住，而不是依赖下游 $ 检测兜底。'''),
    (1303, 'after', r'''从单个命令元素抽路径。抽不出的（复杂元素类型）置 hasUnvalidatablePathArg，由调用方强制 ask。'''),
    (1342, 'before', r'''命名参数分支：-Path value 与 -Path:value 两种语法。'''),
    (1434, 'after', r'''已知开关参数不吃值——下一个参数不能被吞。'''),
    (1463, 'before', r'''未知参数分支：不理解整个调用就整体判不可验证，同时把冒号绑定的值也塞进 paths[]，让 deny 规则至少有机会命中（否则值被困在单个 token 里，paths 为空 = deny 永不生效）。'''),
    (1508, 'after', r'''extractPathsFromCommand 结束。positionalSkip 专治 iwr 的位置 0 是 URL 不是路径。'''),
    (1567, 'after', r'''checkPathConstraints 两遍扫描：先把所有语句过完，deny 永远优先于 ask——否则语句 1 的 ask 先返回，语句 2 的 deny 永远不生效，用户批准了一个含被禁路径的命令。'''),
    (1617, 'after', r'''复合命令含 cd 时，任何语句里的相对路径都不可信：PowerShell 顺序执行，语句 N 的 cd 改变语句 N+1 的解析基准，而校验器按陈旧的 Node 进程 cwd 解析。Set-Location ./.claude; Set-Content ./settings.json 实际写的是 .claude/settings.json（Claude 的权限配置）。连读也挡（finding #27）：Set-Location ~; Get-Content ./.ssh/id_rsa 同样绕过 deny。'''),
    (1628, 'before', r'''管道表达式来源跟踪：'/etc/passwd' | Remove-Item 的路径来自管道，cmdlet 自己没有显式参数，extractPathsFromCommand 返回空路径——整个命令会 passthrough。只要下游出现 cmdlet 且上游是表达式源，强制 ask。'''),
    (1681, 'after', r'''管道来源的路径喂给 deny 猜测器：'.git/hooks/pre-commit' | Remove-Item 应该被 Edit(.git/**) deny 而不是仅仅 ask。'''),
    (1696, 'after', r'''数组字面量/子表达式参数：-Path ./safe.txt, /etc/passwd 在 AST 里是单个 'Other' 元素，合并文本可能落在 cwd 内，而 PowerShell 实际写数组里所有路径。'''),
    (1721, 'after', r'''写 cmdlet 抽不到任何路径也要 ask（Remove-Item 光杆一条 PowerShell 会报错，但不该乐观假设）。optionalWrite 的 iwr/irm 豁免——没有 -OutFile 时输出只进管道。'''),
    (1809, 'after', r'''主循环结束。下面是 nestedCommands（if/for 等控制流里的命令）的第二轮——少了它，if ($true) { Remove-Item / } 会把 deny 降级成 ask。'''),
    (1935, 'after', r'''嵌套命令循环结束，附带 red-team P11/P14 的兜底 ask（step 5 在 powershellPermissions.ts 已用同一机制兜住，这里是双保险）。'''),
    (1990, 'after', r'''嵌套命令的重定向（&& 链等）也要按 'create' 校验——> 是任意路径写入。'''),
    (2049, 'after', r'''文件结束：语句级重定向（> / >> / 2>）同样按 create 校验，合并重定向与 $null 目标跳过。'''),
]
